const OD_arc=(cx,cy,r,a0,a1,col,w,ex='')=>{const p=OD_pt(cx,cy,r,a0),q=OD_pt(cx,cy,r,a1);return `<path d="M${p[0].toFixed(1)},${p[1].toFixed(1)} A${r},${r} 0 0,0 ${q[0].toFixed(1)},${q[1].toFixed(1)}" fill="none" stroke="${col}" stroke-width="${w}" ${ex}/>`};
