/* a fiber side-on, core between yc-hc and yc+hc, cladding cw, from x0 to x1 */
const OD_fiber=(x0,x1,yc,hc,cw,core=OD_CORE)=>`<rect x="${x0}" y="${yc-hc-cw}" width="${x1-x0}" height="${cw}" fill="${OD_CLAD}" stroke="#ADB5BD" stroke-width="2"/><rect x="${x0}" y="${yc+hc}" width="${x1-x0}" height="${cw}" fill="${OD_CLAD}" stroke="#ADB5BD" stroke-width="2"/><rect x="${x0}" y="${yc-hc}" width="${x1-x0}" height="${2*hc}" fill="${core}" stroke="${BLU}" stroke-width="2"/>`;
/* the steep step-index ray (angles exaggerated) and the graded-index sinusoidal ray */
const OD_zig=(x0,x1,yc,hc,per)=>{const p=[[x0,yc]];let x=x0+per/4,y=yc-hc;while(x<x1){p.push([x,y]);x+=per/2;y=(y<yc)?yc+hc:yc-hc}const l=p[p.length-1],dir=l[1]<yc?1:-1;p.push([x1,l[1]+dir*(x1-l[0])*2*hc/(per/2)]);return p};
