/* a narrow arrival pulse at x on a time axis at y */
const OD_pulse=(x,y,h,w,col)=>{const p=[];for(let d=-3*w;d<=3*w+.1;d+=w/4)p.push([x+d,y-h*Math.exp(-d*d/(2*w*w))]);return `<polygon points="${p.map(q=>q[0].toFixed(1)+','+q[1].toFixed(1)).join(' ')}" fill="${col}" fill-opacity=".25" stroke="${col}" stroke-width="3" stroke-linejoin="round"/>`};
