 ICON.odGraded=(x,y)=>`<g transform="translate(${x-210} ${y-165})"><defs><linearGradient id="odGradR" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#EEF2FF"/><stop offset=".5" stop-color="#A5B4FC"/><stop offset="1" stop-color="#EEF2FF"/></linearGradient></defs>${OD_fiber(10,410,90,48,16,'url(#odGradR)')}${OD_arrow(16,90,404,90,BLU,5)}${OD_poly(OD_sin(16,404,90,40,130),ORG,5)}
${OD_L(30,300,400,300,'#ADB5BD',3)}${OD_pulse(208,300,70,8,BLU)}${OD_pulse(214,300,70,8,ORG)}${OD_T(210,200,'δT = 0.31 ns in 5 km',{fs:26,fw:800,a:'middle',fill:GRN})}</g>`;
